import {readFile} from 'node:fs/promises';
const version='20260917000200',name='shared_painting_all_products';
const source=(await readFile(`supabase/migrations/${version}_${name}.sql`,'utf8')).replaceAll('\r',''),literal="'"+source.replaceAll("'","''")+"'";
const conflicts=`select count(*)::int conflicts from (select t.product_id,e.key from public.wc_shop_templates t cross join lateral jsonb_each(t.estimates) e where t.product_id is not null and e.key like 'Painting:%' group by t.product_id,e.key having count(distinct e.value::text)>1) x;`;
const verify=`select exists(select 1 from supabase_migrations.schema_migrations where version='${version}') registered,to_regprocedure('public.wc_save_product_paint_profile(uuid,jsonb,jsonb,boolean,integer)') is not null generic_paint_profile,to_regprocedure('public.wc_shop_auto_snapshot(uuid)') is not null auto_snapshot,(select count(*)::int from wc_shop_templates t cross join lateral jsonb_each(t.estimates) e where e.key like 'Painting:%') structural_paint_keys,coalesce((select strpos(p.prosrc,\$check\$wc_shop_order_finish(item_options,'raw')\$check\$)>0 from pg_proc p where p.oid=to_regprocedure('public.wc_shop_auto_snapshot(uuid)')),false) raw_default;`;
const sql=`begin;select pg_advisory_xact_lock(${version});do $release$ begin if exists(select 1 from supabase_migrations.schema_migrations where version='${version}') then if (select replace(statements[1],E'\\r','') from supabase_migrations.schema_migrations where version='${version}') is distinct from replace(${literal},E'\\r','') then raise exception 'Migration differs';end if;else execute ${literal};insert into supabase_migrations.schema_migrations(version,name,statements) values('${version}','${name}',array[${literal}]);end if;end $release$;commit;${verify}`;
if(process.argv.includes('--print-sql')){process.stdout.write(sql);process.exit(0);}
const token=process.env.SUPABASE_ACCESS_TOKEN;if(!token)throw Error('Supabase access token required');
async function query(query,read_only){const response=await fetch('https://api.supabase.com/v1/projects/zgvnrpspwluapaxnycrg/database/query',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({query,read_only})});if(!response.ok)throw Error(`Production query failed: HTTP ${response.status}: ${(await response.text()).slice(0,500)}`);return response.json();}
const before=(await query(conflicts,true))[0];console.log('Preflight:',JSON.stringify(before));if(before?.conflicts)throw Error('Conflicting Painting estimates must be resolved before migration');
if(process.argv.includes('--apply')){await query(sql,false);const rows=await query(verify,true),after=rows[0];if(!after?.registered||!after?.generic_paint_profile||!after?.auto_snapshot||after?.structural_paint_keys!==0||!after?.raw_default)throw Error('Postflight failed');console.log('Verified:',JSON.stringify(rows));}
